arguments.new_string:
        text_length = self._length
        text_len = len(text)
        if text.style:
            self._spans.append(
                _Span(text_length, text_length + text_len, text.style)
            )
        self._text.append(text.plain)
        # Snapshot spans so appending self to self does not loop forever
        self._spans.extend(
            [
                _Span(start + text_length, end + text_length, style)
                for start, end, style in list(text._spans)
            ]
        )
        self._length += text_len
return self
